          </div>

          {/* Footer CTA to Council */}
          <div className="border-t border-slate-800/90 bg-slate-950/80 px-4 py-3">
            <button
              type="button"
              onClick={() => vegaSource.jumpToStage('council')}
              className="flex w-full items-center justify-between rounded-xl border border-purple-400/40 bg-purple-500/15 px-3.5 py-2 text-xs font-semibold text-purple-200 transition hover:bg-purple-500/25"
            >
              <span>
                {councilSignal
                  ? `Escalate ${councilSignal.severity} to The Council`
                  : 'Preview Council Reasoning'}
              </span>
              <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </motion.aside>
      )}
    </AnimatePresence>
  )
}

import { ChevronDown, ChevronUp, History, Play, SkipBack, SkipForward } from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { useEffect, useState } from 'react'
import { useVegaStore } from '../../store/useVegaStore'

export function ChronosScrubber() {
  const events = useVegaStore((s) => s.events)
  const chronosExpanded = useVegaStore((s) => s.chronosExpanded)
  const setChronosExpanded = useVegaStore((s) => s.setChronosExpanded)
  const chronosCursorIndex = useVegaStore((s) => s.chronosCursorIndex)
  const setChronosCursorIndex = useVegaStore((s) => s.setChronosCursorIndex)
  const selectNode = useVegaStore((s) => s.selectNode)

  const [replaying, setReplaying] = useState(false)

  const activeIndex =
    chronosCursorIndex !== null && chronosCursorIndex < events.length
      ? chronosCursorIndex
      : events.length > 0
        ? events.length - 1
        : null

  const activeEvent = activeIndex !== null ? events[activeIndex] : null

  useEffect(() => {
    if (!replaying || events.length === 0) return
    const id = window.setInterval(() => {
      const current = useVegaStore.getState().chronosCursorIndex ?? 0
      if (current >= events.length - 1) {
        setReplaying(false)
        return
      }
      setChronosCursorIndex(current + 1)
    }, 900)
    return () => window.clearInterval(id)
  }, [replaying, events.length, setChronosCursorIndex])

  return (
    <div className="fixed inset-x-4 bottom-3 z-30">
      <div className="vega-panel overflow-hidden rounded-2xl">
        {/* Collapsed / Header Bar */}
        <div className="flex h-11 items-center justify-between px-4">
          <button
            type="button"
            onClick={() => setChronosExpanded(!chronosExpanded)}
            className="flex items-center gap-2.5 text-left"
          >
            <History className="h-4 w-4 text-purple-400" />
            <span className="font-mono-tabular text-[11px] font-semibold tracking-[0.18em] text-purple-300 uppercase">
              04 / CHRONOS
            </span>
            <span className="hidden text-xs text-slate-400 sm:inline">
              Forensic Timeline ({events.length} events captured)
            </span>
          </button>

          {/* Mini timeline dots preview */}
          <div className="mx-4 hidden flex-1 items-center gap-1.5 overflow-hidden md:flex">
            {events.map((ev, idx) => (
              <button
                key={ev.event_id}
                type="button"
                title={`${ev.event_id} (${ev.source_id} • ${ev.channel})`}
                onClick={() => {
                  setChronosCursorIndex(idx)
                  setChronosExpanded(true)
                }}
                className={`h-2 flex-1 rounded-full transition ${
                  idx === activeIndex
                    ? 'ring-2 ring-amber-300'
                    : ''
                } ${ev.suspicious ? 'bg-red-500/85' : 'bg-sky-500/45 hover:bg-sky-400/75'}`}
              />
            ))}
          </div>

          <button
            type="button"
            onClick={() => setChronosExpanded(!chronosExpanded)}
            className="inline-flex items-center gap-1 rounded-lg border border-slate-800 bg-slate-900/80 px-2.5 py-1 font-mono-tabular text-[10px] text-slate-300 hover:border-purple-400/50"
          >
            <span>{chronosExpanded ? 'COLLAPSE' : 'SCRUB TIMELINE'}</span>
            {chronosExpanded ? (
              <ChevronDown className="h-3.5 w-3.5" />
            ) : (
              <ChevronUp className="h-3.5 w-3.5" />
            )}
          </button>
        </div>

        {/* Expanded Forensic Scrubber */}
        <AnimatePresence>
          {chronosExpanded && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.2 }}
              className="border-t border-slate-800/90 bg-slate-950/85 px-4 py-3"
            >
              {events.length === 0 ? (
                <div className="py-4 text-center text-xs text-slate-400">
                  Waiting for telemetry events to populate Chronos…
                </div>
              ) : (
                <div className="space-y-3">
                  {/* Controls + Slider */}
                  <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1">
                      <button
                        type="button"
                        onClick={() =>
                          setChronosCursorIndex(Math.max(0, (activeIndex ?? 0) - 1))
                        }
                        className="rounded border border-slate-800 bg-slate-900 p-1.5 text-slate-300 hover:border-purple-400/50"
                        title="Previous event"
                      >
                        <SkipBack className="h-3.5 w-3.5" />
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          if (!replaying && (activeIndex ?? 0) >= events.length - 1) {
                            setChronosCursorIndex(0)
                          }
                          setReplaying(!replaying)
                        }}
                        className="inline-flex items-center gap-1 rounded border border-purple-400/40 bg-purple-500/15 px-2.5 py-1 font-mono-tabular text-[11px] text-purple-200 hover:bg-purple-500/25"
                      >
                        <Play className="h-3 w-3" />
                        <span>{replaying ? 'REPLAYING…' : 'REPLAY'}</span>
                      </button>
                      <button
                        type="button"
                        onClick={() =>
                          setChronosCursorIndex(
                            Math.min(events.length - 1, (activeIndex ?? 0) + 1),
                          )
                        }
                        className="rounded border border-slate-800 bg-slate-900 p-1.5 text-slate-300 hover:border-purple-400/50"
                        title="Next event"
                      >
                        <SkipForward className="h-3.5 w-3.5" />
                      </button>
                    </div>

                    <input
                      type="range"
                      min={0}
                      max={Math.max(0, events.length - 1)}
                      value={activeIndex ?? 0}
                      onChange={(e) => {
                        setReplaying(false)
                        setChronosCursorIndex(Number(e.target.value))
                      }}
                      className="h-1.5 flex-1 cursor-pointer accent-purple-400"
                    />

                    <span className="font-mono-tabular text-[11px] text-slate-400">
                      {(activeIndex ?? 0) + 1} / {events.length}
                    </span>
                  </div>

                  {/* Selected Event Forensic Card */}
                  {activeEvent && (
                    <div
                      className={`flex flex-col justify-between gap-3 rounded-xl border p-3 md:flex-row md:items-center ${
                        activeEvent.suspicious
                          ? 'border-red-500/40 bg-red-950/20'
                          : 'border-slate-800 bg-slate-900/60'
                      }`}
                    >
                      <div className="space-y-1">
                        <div className="flex flex-wrap items-center gap-2 font-mono-tabular text-[11px]">
                          <span className="font-bold text-white">{activeEvent.event_id}</span>
                          <span className="rounded bg-slate-800 px-1.5 py-0.5 text-sky-300">
                            {activeEvent.source_id}
                          </span>
                          <span className="rounded bg-slate-800 px-1.5 py-0.5 text-purple-300 uppercase">
                            {activeEvent.channel}
                          </span>
                          <span className="text-slate-400">{activeEvent.event_time}</span>
                        </div>
                        <div className="text-xs font-medium text-slate-100">
                          {activeEvent.summary}
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        <code className="max-w-md truncate rounded bg-black/50 px-2.5 py-1 font-mono-tabular text-[10px] text-slate-300">
                          {JSON.stringify(activeEvent.payload)}
                        </code>
                        <button
                          type="button"
                          onClick={() => selectNode(activeEvent.source_id)}
                          className="shrink-0 rounded-lg border border-slate-700 bg-slate-900 px-2.5 py-1 font-mono-tabular text-[10px] text-slate-200 hover:border-sky-400/50"
                        >
                          Focus {activeEvent.source_id}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

import { MessageSquareCode, Send, Sparkles, X } from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { useState } from 'react'
import { SCENARIOS } from '../../data/scenarios'
import { vegaSource } from '../../engine/mockSource'
import { useVegaStore } from '../../store/useVegaStore'

export function ObserverDrawer() {
  const observerOpen = useVegaStore((s) => s.observerOpen)
  const setObserverOpen = useVegaStore((s) => s.setObserverOpen)
  const observerMessages = useVegaStore((s) => s.observerMessages)
  const scenarioId = useVegaStore((s) => s.scenarioId)
  const selectEvent = useVegaStore((s) => s.selectEvent)
  const setChronosExpanded = useVegaStore((s) => s.setChronosExpanded)

  const [input, setInput] = useState('')
  const presets = SCENARIOS[scenarioId].observerPresets

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!input.trim()) return
    vegaSource.askObserver(input)
    setInput('')
  }

  const handleCitationClick = (eventId: string) => {
    selectEvent(eventId)
    setChronosExpanded(true)
  }

  return (
    <AnimatePresence>
      {observerOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setObserverOpen(false)}
            className="fixed inset-0 z-40 bg-black/55 backdrop-blur-xs"
          />

          <motion.aside
            initial={{ x: 480 }}
            animate={{ x: 0 }}
            exit={{ x: 480 }}
            transition={{ type: 'spring', stiffness: 340, damping: 34 }}
            className="vega-panel fixed top-3 right-3 bottom-3 z-50 flex w-[460px] max-w-[calc(100vw-1.5rem)] flex-col overflow-hidden rounded-2xl"
          >
            {/* Header */}
            <div className="flex items-center justify-between border-b border-slate-800 px-4 py-3">
              <div>
                <div className="flex items-center gap-2 font-mono-tabular text-[10px] tracking-[0.2em] text-sky-400 uppercase">
                  <MessageSquareCode className="h-3.5 w-3.5" />
                  <span>06 / VEGA CORE — THE OBSERVER</span>
                </div>
                <h2 className="mt-0.5 text-sm font-bold text-white">
                  Conversational Evidence Intelligence
                </h2>
              </div>
              <button
                type="button"
                onClick={() => setObserverOpen(false)}
                className="rounded-lg p-1 text-slate-400 hover:bg-slate-800 hover:text-white"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            {/* Suggested Judge Prompts */}
            <div className="border-b border-slate-800/80 bg-slate-950/60 px-4 py-2.5">
              <div className="mb-1.5 flex items-center gap-1 font-mono-tabular text-[10px] text-slate-400 uppercase">
                <Sparkles className="h-3 w-3 text-purple-400" />
                <span>Suggested Queries</span>
              </div>
              <div className="flex flex-wrap gap-1.5">
                {presets.map((p) => (
                  <button
                    key={p.id}
                    type="button"
                    onClick={() => vegaSource.askObserver(p.prompt)}
                    className="rounded-lg border border-slate-700/80 bg-slate-900/90 px-2.5 py-1 text-left text-[11px] text-slate-200 transition hover:border-sky-400/50 hover:text-white"
                  >
                    {p.prompt}
                  </button>
                ))}
              </div>
            </div>

            {/* Conversation Feed */}
            <div className="flex-1 space-y-3 overflow-y-auto p-4">
              {observerMessages.length === 0 ? (
                <div className="rounded-xl border border-dashed border-slate-800 bg-slate-950/40 p-4 text-xs leading-relaxed text-slate-400">
                  Ask VEGA to explain why a node was flagged, inspect competing hypotheses, or
                  verify privacy & TTL guarantees. Every answer links directly to preserved{' '}
                  <span className="font-mono-tabular text-sky-300">event_id</span> evidence.
                </div>
              ) : (
                observerMessages.map((msg) => (
                  <div
                    key={msg.id}
                    className={`rounded-xl border p-3 text-xs ${
                      msg.role === 'user'
                        ? 'ml-8 border-sky-500/30 bg-sky-950/25 text-sky-100'
                        : 'mr-4 border-slate-800 bg-slate-900/80 text-slate-200'
                    }`}
                  >
                    <div className="mb-1 flex items-center justify-between font-mono-tabular text-[10px] text-slate-400">
                      <span>{msg.role === 'user' ? 'OPERATOR' : 'VEGA OBSERVER'}</span>
                      <span>{msg.timestamp}</span>
                    </div>
                    <p className="leading-relaxed">{msg.text}</p>

                    {msg.qa && (
                      <div className="mt-2.5 space-y-2 border-t border-slate-800 pt-2">
                        <ul className="list-disc space-y-1 pl-4 text-[11px] text-slate-300">
                          {msg.qa.summary_bullets.map((b) => (
                            <li key={b}>{b}</li>
                          ))}
                        </ul>

                        {msg.qa.cited_event_ids.length > 0 && (
                          <div className="flex flex-wrap items-center gap-1 pt-1">
                            <span className="font-mono-tabular text-[10px] text-slate-400">
                              EVIDENCE:
                            </span>
                            {msg.qa.cited_event_ids.map((eid) => (
                              <button
                                key={eid}
                                type="button"
                                onClick={() => handleCitationClick(eid)}
                                className="rounded border border-sky-400/35 bg-sky-500/10 px-1.5 py-0.5 font-mono-tabular text-[10px] text-sky-200 hover:border-sky-300"
                              >
                                {eid}
                              </button>
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            {/* Input */}
            <form
              onSubmit={handleSubmit}
              className="flex items-center gap-2 border-t border-slate-800 bg-slate-950/90 p-3"
            >
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask VEGA about subj-042, policies, or evidence…"
                className="flex-1 rounded-xl border border-slate-800 bg-slate-900 px-3 py-2 text-xs text-white placeholder:text-slate-500 focus:border-sky-400/60 focus:outline-none"
              />
              <button
                type="submit"
                className="inline-flex items-center justify-center rounded-xl border border-sky-400/50 bg-sky-500/20 p-2 text-sky-200 hover:bg-sky-500/30"
              >
                <Send className="h-4 w-4" />
              </button>
            </form>
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  )
}

import { useEffect } from 'react'
import { PresenterBar } from './components/layout/PresenterBar'
import { TopHud } from './components/layout/TopHud'
import { ChronosScrubber } from './components/overlays/ChronosScrubber'
import { ObserverDrawer } from './components/overlays/ObserverDrawer'
import { BlackoutOverlay } from './components/stages/BlackoutOverlay'
import { CouncilView } from './components/stages/CouncilView'
import { GhostProtocolPanel } from './components/stages/GhostProtocolPanel'
import { PanopticonCanvas } from './components/stages/PanopticonCanvas'
import { vegaSource } from './engine/mockSource'
import { useVegaStore } from './store/useVegaStore'

export function App() {
  const threatMode = useVegaStore((s) => s.threatMode)

  useEffect(() => {
    vegaSource.start('sev1-exfil')
    return () => vegaSource.stop()
  }, [])

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault()
        const current = useVegaStore.getState().observerOpen
        useVegaStore.getState().setObserverOpen(!current)
      } else if (e.shiftKey && e.key.toLowerCase() === 'd') {
        e.preventDefault()
        const current = useVegaStore.getState().presenterOpen
        useVegaStore.getState().setPresenterOpen(!current)
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  return (
    <div
      data-threat-mode={threatMode}
      className="relative flex h-screen w-screen flex-col overflow-hidden bg-[#050811] text-slate-100"
    >
      <TopHud />
      <PresenterBar />

      <main className="relative flex-1 overflow-hidden">
        <PanopticonCanvas />
        <GhostProtocolPanel />
        <CouncilView />
        <BlackoutOverlay />
      </main>

      <ChronosScrubber />
      <ObserverDrawer />
    </div>
  )
}

export default App

