import { useVegaStore } from '../../store/useVegaStore'
import { VegaEye } from './VegaEye'

const STATUS_LABEL = {
  idle: 'Monitoring. No anomalies detected.',
  alert: 'Anomaly detected.',
  investigating: 'Council investigation in progress.',
} as const

export function VegaBrand({ onRecenter }: { onRecenter: () => void }) {
  const state = useVegaStore((s) => {
    if (s.stage === 'blackout' && s.wardenDecision) return null
    if (s.councilSignal) return 'investigating'
    if (s.threatMode !== 'WATCH' || s.findings.length > 0 || s.events.some((event) => event.suspicious)) {
      return 'alert'
    }
    return 'idle'
  })

  if (!state) return null

  return (
    <>
      <span id="vega-eye-status" role="status" className="sr-only">
        {STATUS_LABEL[state]}
      </span>
      <button
        type="button"
        onClick={onRecenter}
        aria-label="VEGA — recenter topology"
        aria-describedby="vega-eye-status"
        title={`${STATUS_LABEL[state]} Click to recenter.`}
        className="vega-glass absolute top-4 left-1/2 z-30 inline-flex min-h-14 -translate-x-1/2 cursor-pointer items-center gap-3 rounded-full px-5 text-slate-100 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-sky-300 sm:min-h-16 sm:px-6"
      >
        <VegaEye
          state={state}
          className={`h-auto w-10 shrink-0 sm:w-11 ${state === 'investigating' ? 'text-violet-300' : 'text-emerald-300'}`}
        />
        {/* Original angular lettering; no third-party display font required. */}
        <svg aria-hidden="true" focusable="false" viewBox="0 0 144 48" fill="currentColor" className="h-auto w-24 shrink-0 sm:w-28">
          <path d="M0 3h10l8 26 7-26h10L21 45l-8-6Z" />
          <path d="M38 3h29l-3 8H47v7h15l-3 7H47v6h16l-3 8H38Z" />
          <path d="M79 3h23l-3 8H83l-5 5v12l5 4h10v-7h-7l3-7h13v16l-6 5H79l-10-8V12Z" />
          <path fillRule="evenodd" d="M117 3h12l15 43-11-5-4-9h-13l-3 7h-10Zm1 22h9l-5-14Z" />
        </svg>
      </button>
    </>
  )
}

import { useEffect } from 'react'
import { PresenterBar } from './components/layout/PresenterBar'
import { ChronosScrubber } from './components/overlays/ChronosScrubber'
import { ObserverDrawer } from './components/overlays/ObserverDrawer'
import { BlackoutOverlay } from './components/stages/BlackoutOverlay'
import { CouncilView } from './components/stages/CouncilView'
import { GhostProtocolPanel } from './components/stages/GhostProtocolPanel'
import { PanopticonCanvas } from './components/stages/PanopticonCanvas'
import { switchDataMode, vegaSource } from './engine/sourceManager'
import { useVegaStore } from './store/useVegaStore'

const API_BASE = (import.meta.env.VITE_API_BASE_URL as string | undefined) ?? ''

export function App() {
  const threatMode = useVegaStore((s) => s.threatMode)
  const wardenDecisionId = useVegaStore((s) => s.wardenDecision?.decision_id)
  const setStage = useVegaStore((s) => s.setStage)

  useEffect(() => {
    // Open the Warden view once per decision; execution updates don't interrupt navigation.
    if (wardenDecisionId) setStage('blackout')
  }, [wardenDecisionId, setStage])

  useEffect(() => {
    let cancelled = false
    const controller = new AbortController()
    const timeoutId = window.setTimeout(() => controller.abort(), 500)

    fetch(`${API_BASE}/health`, { signal: controller.signal })
      .then((res) => {
        if (cancelled) return
        if (res.ok) {
          switchDataMode('LIVE', true)
        } else {
          switchDataMode('SIMULATED', true)
        }
      })
      .catch(() => {
        if (!cancelled) {
          switchDataMode('SIMULATED', true)
        }
      })
      .finally(() => {
        window.clearTimeout(timeoutId)
      })

    return () => {
      cancelled = true
      controller.abort()
      window.clearTimeout(timeoutId)
      vegaSource.stop()
    }
  }, [])

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault()
        const current = useVegaStore.getState().observerOpen
        useVegaStore.getState().setObserverOpen(!current)
      } else if (e.shiftKey && e.key.toLowerCase() === 'd') {
        e.preventDefault()
        const current = useVegaStore.getState().presenterOpen
        useVegaStore.getState().setPresenterOpen(!current)
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  return (
    <div
      data-threat-mode={threatMode}
      className="relative h-dvh w-full overflow-hidden bg-[#050811] text-slate-100"
    >
      <PresenterBar />

      <main className="relative h-full overflow-clip">
        <PanopticonCanvas />
        <GhostProtocolPanel />
        <CouncilView />
        <BlackoutOverlay />
      </main>

      <ChronosScrubber />
      <ObserverDrawer />
    </div>
  )
}

export default App

