import { Activity, Lock, Pause, Play } from 'lucide-react'
import { useEffect, useMemo, useState } from 'react'
import { formatTtl, measureTelemetry, sampleTelemetry } from '../../engine/telemetryMetrics'
import { useVegaStore } from '../../store/useVegaStore'

const count = new Intl.NumberFormat()

export function TelemetryTicker() {
  const dataMode = useVegaStore((s) => s.dataMode)
  const liveStatus = useVegaStore((s) => s.liveStatus)
  const hasWindowData = useVegaStore((s) => s.windows.length > 0)
  const windowId = useVegaStore((s) => s.activeWindowId)
  const ttl = useVegaStore((s) => s.ttlSecondsRemaining)
  const nodes = useVegaStore((s) => s.nodes)
  const events = useVegaStore((s) => s.events)
  const snapshotSaved = useVegaStore((s) => s.councilSignal?.snapshot_preserved)
  const [now, setNow] = useState(() => Date.now())
  const [paused, setPaused] = useState(false)
  const simulated = dataMode === 'SIMULATED'
  const liveReady = liveStatus === 'connected' && hasWindowData
  const available = simulated || liveReady

  useEffect(() => {
    if (!liveReady || simulated) return
    const tick = () => setNow(Date.now())
    const frame = window.requestAnimationFrame(tick)
    const timer = window.setInterval(tick, 1000)
    return () => {
      window.cancelAnimationFrame(frame)
      window.clearInterval(timer)
    }
  }, [simulated, liveReady])

  const { samples, latestIngest, captured, flagged } = useMemo(() => sampleTelemetry(events), [events])
  const { eventsPerMinute, online, monitored } = measureTelemetry(
    samples,
    nodes,
    simulated ? latestIngest : now,
    dataMode,
  )
  const sourceLabel = simulated ? 'Replay' : liveReady ? 'Live' : liveStatus === 'disconnected' ? 'Offline' : 'Connecting'
  const sourceTone = sourceLabel === 'Live' ? 'bg-emerald-400' : sourceLabel === 'Offline' ? 'bg-rose-400' : 'bg-amber-300'

  const metrics = (
    <>
      <div className="vega-ticker-item" title="Telemetry source status">
        <dt className="sr-only">Source</dt>
        <dd className="flex items-center gap-2 text-[10px] tracking-wider text-slate-200 uppercase">
          <span aria-hidden="true" className={`size-1.5 rounded-full ${sourceTone}`} />
          {sourceLabel}
        </dd>
      </div>
      <Metric
        label="Ingest rate"
        value={available ? count.format(eventsPerMinute) : '—'}
        unit={available ? 'evt/min' : undefined}
        note={simulated ? '60 seconds of recorded ingest time, ending at the latest replayed event.' : 'Events ingested in the last 60 seconds.'}
      />
      <Metric label="TTL" value={available ? formatTtl(ttl) : '—'} note="Telemetry retention countdown (minutes:seconds)." />
      <Metric label="Active window" value={available ? windowId : '—'} />
      <Metric
        label="Nodes online"
        value={available ? `${online}/${monitored}` : '—'}
        note={simulated ? 'Simulated endpoints with a recent heartbeat, excluding isolated nodes and VEGA-CORE.' : 'Non-isolated endpoints with telemetry in the last 2 minutes. VEGA-CORE is not counted.'}
      />
      <Metric label="Captured" value={available ? count.format(captured) : '—'} note="Events currently loaded into the dashboard." />
      <Metric label="Flagged" value={available ? count.format(flagged) : '—'} note="Captured events marked suspicious." />
      {available && snapshotSaved && (
        <div className="vega-ticker-item">
          <dt className="sr-only">Evidence</dt>
          <dd className="flex items-center gap-1.5 text-emerald-300">
            <Lock aria-hidden="true" className="size-3" />
            Snapshot preserved
          </dd>
        </div>
      )}
    </>
  )

  return (
    <aside className="vega-ticker pointer-events-auto flex" aria-labelledby="telemetry-heading">
      <h2
        id="telemetry-heading"
        className="flex shrink-0 items-center gap-2 border-r border-slate-400/15 px-3 text-xs font-semibold text-slate-200 sm:px-6"
      >
        <Activity aria-hidden="true" className="size-3.5 text-sky-300" />
        Telemetry
      </h2>
      <div className="vega-ticker-window min-w-0 flex-1">
        <div className="vega-ticker-track font-mono-tabular text-[11px]" data-paused={paused}>
          <dl className="vega-ticker-cycle">{metrics}</dl>
          <dl className="vega-ticker-cycle" aria-hidden="true">{metrics}</dl>
        </div>
      </div>
      <button
        type="button"
        onClick={() => setPaused((current) => !current)}
        aria-label={paused ? 'Resume telemetry ticker' : 'Pause telemetry ticker'}
        title={paused ? 'Resume telemetry ticker' : 'Pause telemetry ticker'}
        className="vega-ticker-toggle grid w-10 shrink-0 cursor-pointer place-items-center border-l border-slate-400/15 text-slate-300 hover:bg-white/5 hover:text-white focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sky-300"
      >
        {paused ? <Play aria-hidden="true" className="size-3.5" /> : <Pause aria-hidden="true" className="size-3.5" />}
      </button>
    </aside>
  )
}

function Metric({ label, value, unit, note }: { label: string; value: string; unit?: string; note?: string }) {
  return (
    <div className="vega-ticker-item" title={note}>
      <dt className="text-slate-400">
        {label}
        {note && <span className="sr-only"> ({note})</span>}
      </dt>
      <dd className="font-medium text-slate-100">
        {value}
        {unit && (
          <>
            <span aria-hidden="true" className="ml-1 text-[9px] font-normal text-slate-400">{unit}</span>
            <span className="sr-only"> events per minute</span>
          </>
        )}
      </dd>
    </div>
  )
}

@import "tailwindcss";

@layer base {
  :root {
    --vega-bg: #050811;
    --vega-surface: rgba(10, 16, 30, 0.78);
    --vega-border: rgba(148, 163, 184, 0.16);
    --vega-accent: #38bdf8;
    --vega-accent-glow: rgba(56, 189, 248, 0.28);
    --vega-oracle: #7851a9;
    --vega-warden: #ef4444;
    --font-sans: 'Space Grotesk', ui-sans-serif, system-ui, -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  }

  [data-threat-mode='WATCH'] {
    --vega-accent: #38bdf8;
    --vega-accent-glow: rgba(56, 189, 248, 0.28);
  }

  [data-threat-mode='INVESTIGATE'] {
    --vega-accent: var(--vega-oracle);
    --vega-accent-glow: color-mix(in srgb, var(--vega-oracle) 32%, transparent);
  }

  [data-threat-mode='SEV1_ESCALATION'],
  [data-threat-mode='CONTAINED'] {
    --vega-accent: #ef4444;
    --vega-accent-glow: rgba(239, 68, 68, 0.38);
  }

  html,
  body,
  #root {
    height: 100%;
    width: 100%;
    overflow: hidden;
    font-family: var(--font-sans);
    background-color: var(--vega-bg);
  }
}

.font-mono-tabular {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.vega-panel {
  background: var(--vega-surface);
  border: 1px solid var(--vega-border);
  backdrop-filter: blur(14px);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.02) inset, 0 20px 50px rgba(0, 0, 0, 0.55);
}

.vega-glass::before {
  content: '';
  position: absolute;
  inset: -0.5rem -1.5rem;
  z-index: -1;
  pointer-events: none;
  background: rgba(5, 8, 17, 0.14);
  backdrop-filter: blur(7px) saturate(120%) brightness(0.85);
  /* Feather the blur into the graph instead of outlining the button. */
  mask-image: radial-gradient(ellipse closest-side, #000 32%, rgba(0, 0, 0, 0.75) 60%, transparent);
}

.vega-dashboard-header {
  background: linear-gradient(180deg, rgba(14, 20, 33, 0.82), rgba(9, 14, 24, 0.72));
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  backdrop-filter: blur(10px);
}

.vega-ticker {
  background: rgba(19, 26, 41, 0.82);
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  backdrop-filter: blur(8px);
}

.vega-ticker-window {
  overflow: clip;
  mask-image: linear-gradient(to right, transparent, #000 8px, #000 calc(100% - 8px), transparent);
}

.vega-ticker-track {
  display: flex;
  width: max-content;
  min-width: 200%;
  animation: vega-ticker-scroll 34s linear infinite;
}

.vega-ticker-cycle {
  display: flex;
  flex: 1 0 auto;
}

.vega-ticker-item {
  display: flex;
  flex: 1 0 auto;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.25rem;
  padding-inline: 1rem;
  border-inline-end: 1px solid rgba(148, 163, 184, 0.12);
  white-space: nowrap;
}

.vega-ticker-track[data-paused='true'] {
  animation-play-state: paused;
}

@media (hover: hover) {
  .vega-ticker-window:hover .vega-ticker-track {
    animation-play-state: paused;
  }
}

@keyframes vega-ticker-scroll {
  to { transform: translateX(-50%); }
}

[data-eye-state='idle'],
[data-eye-state='alert'],
[data-core-state='idle'],
[data-core-state='alert'] {
  --vega-state-color: #6ee7b7;
}

[data-eye-state='investigating'],
[data-core-state='investigating'] {
  --vega-state-color: var(--vega-oracle);
}

[data-eye-state='warden'] {
  --vega-state-color: var(--color-red-400);
}

[data-eye-state] {
  color: var(--vega-state-color);
}

.vega-core {
  --core-tint: var(--vega-state-color, #38bdf8);
  background-color: color-mix(in srgb, var(--core-tint) 20%, var(--vega-bg));
  border-color: color-mix(in srgb, var(--core-tint) 72%, transparent);
  box-shadow: 0 0 30px color-mix(in srgb, var(--core-tint) 23%, transparent);
}

.vega-eye-scan {
  animation: vega-eye-scan 4s ease-in-out infinite;
}

@keyframes vega-eye-scan {
  0%, 12%, 82%, 100% { transform: translateX(0); }
  23%, 42% { transform: translateX(-3.4px); }
  55%, 72% { transform: translateX(3.4px); }
}

@media (prefers-reduced-motion: reduce) {
  .vega-eye-scan {
    animation: none;
  }

  .vega-ticker-window {
    mask-image: none;
  }

  .vega-ticker-track {
    width: auto;
    min-width: 0;
    animation: none;
  }

  .vega-ticker-cycle {
    flex: 1 1 auto;
    flex-wrap: wrap;
  }

  .vega-ticker-cycle[aria-hidden='true'],
  .vega-ticker-toggle {
    display: none;
  }

  .vega-ticker-item {
    min-height: 1.75rem;
    padding-inline: 0.75rem;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .vega-dashboard-header {
    background: #0e1421;
    backdrop-filter: none;
  }

  .vega-ticker {
    background: #131a29;
    backdrop-filter: none;
  }

  .vega-glass {
    background: var(--vega-bg);
  }

  .vega-glass::before {
    content: none;
  }
}

.vega-scanlines {
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.015) 0px,
    rgba(255, 255, 255, 0.015) 1px,
    transparent 1px,
    transparent 3px
  );
}

/* Custom subtle scrollbars for telemetry logs */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: rgba(15, 23, 42, 0.4);
}
::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.25);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(148, 163, 184, 0.45);
}

