from http.client import HTTPConnection
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

SOURCES = {'10.97.0.28', '10.97.0.241', '10.97.0.25'}
LIMIT = 65536


class IngestRelay(BaseHTTPRequestHandler):
    def forward(self, method, path, body=None):
        conn = HTTPConnection('127.0.0.1', 8000, timeout=3)
        try:
            conn.request(method, path, body=body, headers={'Content-Type': 'application/json'})
            response = conn.getresponse()
            status = response.status
            payload = response.read(LIMIT + 1)
            if len(payload) > LIMIT:
                raise ValueError('Upstream response exceeds limit')
        except (OSError, ValueError):
            self.send_error(502, 'VEGA backend unavailable')
            return
        finally:
            conn.close()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_GET(self):
        if self.client_address[0] not in SOURCES:
            return self.send_error(403)
        if self.path != '/health':
            return self.send_error(404)
        self.forward('GET', '/health')

    def do_POST(self):
        if self.client_address[0] not in SOURCES:
            return self.send_error(403)
        if self.path != '/events':
            return self.send_error(404)
        try:
            length = int(self.headers.get('Content-Length', ''))
        except ValueError:
            return self.send_error(411)
        if not 0 < length <= LIMIT:
            return self.send_error(413)
        if self.headers.get_content_type() != 'application/json':
            return self.send_error(415)
        self.connection.settimeout(3)
        payload = self.rfile.read(length)
        if len(payload) != length:
            return self.send_error(400)
        self.forward('POST', '/events', payload)


ThreadingHTTPServer(('10.97.0.1', 8001), IngestRelay).serve_forever()

